use spore_core::{creature_skin_corner_lookup_v1 as l,creature_skin_corner_sample_v1 as s,native_sse::Policy};use std::io::Write;
fn main(){let mut bytes=Vec::new();for case in 0..3 {let key=0x00123456u32;let first=(l::corner_hash(key)&0x7fff) as usize;let slot=if case==2{0x7fff}else{first};let mut keys=vec![if case==2{0}else{u32::MAX};l::SLOT_COUNT];let mut vals=vec![[0;2];l::SLOT_COUNT];if case==0{keys[first]=key;vals[first]=[0x12345678,17];}let mut records=[[77;6];1];let(mut status,mut count,mut out,mut calls)=(2,0,[9,10],0);s::sample(key,&mut keys,&mut vals,&mut records,&mut status,&mut count,&mut out,[0.;3],0.5,Policy::Mxcsr1f80,|_,o|{calls+=1;*o=[0x3f800000,0x99999999]}).unwrap();for v in [status,count,out[0],out[1]].into_iter().chain(records[0]).chain([keys[slot],vals[slot][0],vals[slot][1],calls]) {bytes.extend_from_slice(&v.to_le_bytes());}}std::io::stdout().write_all(&bytes).unwrap();}
